package com.medcore.backend.api.internaciones;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="internaciones")public class Internacion{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="paciente_id",nullable=false)private Long pacienteId;@Column(name="profesional_id",nullable=false)private Long profesionalId;@Column(name="fecha_ingreso",nullable=false)private LocalDateTime fechaIngreso;@Column(name="fecha_alta")private LocalDateTime fechaAlta;@Column(name="motivo_internacion",nullable=false,length=500)private String motivoInternacion;@Column(name="diagnostico_ingreso",length=3000)private String diagnosticoIngreso;@Enumerated(EnumType.STRING)@Column(nullable=false)private EstadoInternacion estado;@Column(name="cama_id",nullable=false)private Long camaId;@Column(name="admision_id")private Long admisionId;
@PrePersist void init(){if(fechaIngreso==null)fechaIngreso=LocalDateTime.now(ZoneId.of("America/Argentina/Buenos_Aires"));if(estado==null)estado=EstadoInternacion.ACTIVA;}public Long getId(){return id;}public void setId(Long v){id=v;}public Long getPacienteId(){return pacienteId;}public void setPacienteId(Long v){pacienteId=v;}public Long getProfesionalId(){return profesionalId;}public void setProfesionalId(Long v){profesionalId=v;}public LocalDateTime getFechaIngreso(){return fechaIngreso;}public void setFechaIngreso(LocalDateTime v){fechaIngreso=v;}public LocalDateTime getFechaAlta(){return fechaAlta;}public void setFechaAlta(LocalDateTime v){fechaAlta=v;}public String getMotivoInternacion(){return motivoInternacion;}public void setMotivoInternacion(String v){motivoInternacion=v;}public String getDiagnosticoIngreso(){return diagnosticoIngreso;}public void setDiagnosticoIngreso(String v){diagnosticoIngreso=v;}public EstadoInternacion getEstado(){return estado;}public void setEstado(EstadoInternacion v){estado=v;}public Long getCamaId(){return camaId;}public void setCamaId(Long v){camaId=v;}public Long getAdmisionId(){return admisionId;}public void setAdmisionId(Long v){admisionId=v;}}
